/**
 * SMZ Coaches V2 — Power Card art assets, embedded as base64.
 *
 * Embedded (not loaded as separate files) so canvas.toDataURL()
 * works under Safari's file:// restrictions during local testing —
 * a canvas becomes "tainted" (blocking data export) once a
 * cross-file image is drawn onto it under file://, but data: URIs
 * are always treated as same-origin. Same reasoning as the loader
 * card's embedded front/back images in cards.css.
 */

const CARD_ASSETS = {
  front: "data:image/jpeg;base64,",
  back: "data:image/jpeg;base64,",
  logo: "data:image/png;base64,",
  icons: [
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
  ],
  grps: [
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
  ],
};
